	let offsetX, offsetY;
	for(a = 0, y = 0; y < DIAGONAL_SAMPLES; ++y) {
		for(x = 0; x < DIAGONAL_SAMPLES; ++x) {
			offsetX = x / (DIAGONAL_SAMPLES - 1.0);
