function callEngineScripts (engines, project_dir) {
    return Promise.all(
        engines.map(function (engine) {
            var scriptPath = engine.scriptSrc || null;
            if (scriptPath && (isWindows || fs.existsSync(engine.scriptSrc))) {
                if (!isWindows) {  
                    fs.chmodSync(engine.scriptSrc, '755');
