async function getPIDsListeningOnPort (port, filteringFunc = null) {
  const result = [];
  try {
    const {stdout} = await exec('lsof', ['-ti', `tcp:${port}`]);
    result.push(...(stdout.trim().split(/\n+/)));
  } catch (e) {
    return result;
