function consumePair(stream, close, open) {
	const start = stream.pos;
	if (stream.eat(close)) {
		while (!stream.sol()) {
			if (stream.eat(open)) {
				return true;
			}
			stream.pos--;
		}
	}
	stream.pos = start;
	return false;
}

