function consumeArray(stream, arr) {
	const start = stream.pos;
	let consumed = false;
	for (let i = arr.length - 1; i >= 0 && !stream.sol(); i--) {
		if (!stream.eat(arr[i])) {
			break;
		}
		consumed = i === 0;
	}
	if (!consumed) {
		stream.pos = start;
	}
	return consumed;
}

