			callback = context;
			context = this._context;
		}
		if (this.isAsync) {
			var asyncArgs = this._arguments.slice();
			asyncArgs.push(callback);
			this.fn.apply(context, asyncArgs);
		} else {
			if (callback) {
				try {
					callback(null, this.fn.apply(context, this._arguments));
