function buildOptions (options) {
  var result = [];
  var keys = Object.keys(options);
  keys.forEach(function (key) {
    var props = options[key];
    if (is.string(props)) {
      props = {
        type: props
      };
    }
    var name = [
      format('--%s', dasherize(key))
