function run(context, fn, finish, args) {
	if (typeof context == 'function') {  
		args = finish;
		finish = fn;
		fn = context;
		context = this;
	}
	if (isPromise(fn)) {  
		fn
			.then(function(value) {
				finish.apply(context, [null, value]);
			})
			.catch(function(err) {
				finish.call(context, err || 'An error occured');
			});
