				.then(function(value) {  
					finish.apply(context, [null, value]);
				})
				.catch(function(err) {
					finish.call(context, err || 'An error occured');
				});
		}
	} else {  
		var result;
		try {
			result = fn.apply(context, args || []);  
		} catch (e) {
			finish.call(context, e);
		}
		if (isPromise(result)) {  
