	// Build plugins
	if (_options.build.plugins) {
		theme['plugins'] = {};
		_.each(_options.build.plugins, function(plugin) {
			luiTheme('plugins.' + plugin);
		});
	}

	output = tosass.format({theme: theme, imports: imports});

	if (typeof(callback) === 'function') {
		callback(output);
	}
	return output;
