  ['method', 'url'].forEach(function (prop) {
    response[prop] = req[prop];
  });

  // Append select `res` properties
  ['headers', 'statusCode'].forEach(function (prop) {
    response[prop] = res[prop];
  });

  response.body = body;

  return response;
}

