        var packagePath = path.join( current, project, 'package.json' );

        // First, get the datas
        var pack = JSON.parse( fs.readFileSync( packagePath ));

        // Add the properties in the object
        pack.name = project;
        pack.version = '0.0.1';
        pack.dependencies = {
            'tartempion': '0.0.x'
        };

        // And write the object to the package.json file
