function sshCommandSequence(connection, commands, fnOutput) {
  var allResults = [];
  var successHandler = function(nextPromise){
    return function(result) {
      if( result !== true) {   
        allResults.push(result);
      }
      return nextPromise();
    };
  };
  var errorHandler = function(nextPromise) {
    return function(error) {
      allResults.push(error);
      return nextPromise();
    };
  };
  var result = Q(true);
  commands.map(function(command){
    return function() {
			return sshExecSingleCommand(connection, command, fnOutput);
		};
  }).forEach(function (f) {
    result = result.then(
      successHandler(f),
      errorHandler(f)
    );
  });
  return result.then(
  	function(finalResult){
      allResults.push(finalResult);
      return allResults;
    },
    function(error) {
      allResults.push(error);
      return allResults;
  });
}

