function render(url) {
  return async page => {
    try {
      const template = `${page.template || 'schedule'}.hbs`;
      const filePath = path.join(
        process.cwd(),
        config.theme || 'theme',
        config.template || 'templates',
        template,
      );
      const output = Handlebars.compile(await fs.readFile(filePath, 'utf-8'))(page);
