      const dir = url !== 'index' ? path.join(outputDir, url) : outputDir;
      await fs.ensureDir(dir);
      await fs.writeFile(path.join(dir, 'index.html'), output, 'utf8');
    } catch (err) {
      throw err;
    }
  };
}

